var MAX_TRIAGE_FAILURES = 3;
var TRIAGE_FAILURE_MARKER = "<!-- triagebot:triage-failed -->";
function packageDirsFromChangedFiles(changedFiles) {
  const packageDirs = /* @__PURE__ */ new Set();
  for (const file2 of changedFiles) {
    const match4 = file2.match(/^(packages\/(?:integrations\/)?[^/]+)\//);
    if (match4) packageDirs.add(match4[1]);
  }
  return [...packageDirs];
}
async function publishPreviewRelease(session) {
  console.info("Preview release: checking changed package directories.");
  const diffResult = await session.shell("git diff main --name-only");
  if (!diffResult.stdout.trim()) {
    console.info("Preview release skipped: no changed files relative to main.");
    return null;
  }
  const changedFiles = diffResult.stdout.trim().split("\n");
  const packageDirs = packageDirsFromChangedFiles(changedFiles);
  console.info("Preview release changed package directories:", packageDirs);
  if (packageDirs.length === 0) {
    console.info("Preview release skipped: no changed packages under packages/.");
    return null;
  }
  const packages = packageDirs.join(" ");
  console.info(`Preview release: publishing packages ${packages}.`);
  const publishResult = await session.shell(
    `pnpm dlx pkg-pr-new publish --pnpm --compact --no-template --comment=off --json preview-release.json ${packages}`
  );
  if (publishResult.exitCode !== 0) {
    console.warn("Preview release publish failed:", publishResult.stderr || publishResult.stdout);
    return null;
  }
  const jsonResult = await session.shell(
    `node -e "process.stdout.write(require('fs').readFileSync('preview-release.json','utf8'))"`
  );
  try {
    const output = JSON.parse(jsonResult.stdout.trim());
    const urls = (output.packages ?? []).map((pkg) => pkg.url).filter((url2) => typeof url2 === "string" && url2.length > 0);
    if (urls.length === 0) {
      console.warn("Preview release JSON contained no package URLs.");
      return null;
    }
    return { urls };
  } catch (err2) {
    console.warn("Failed to parse preview release JSON output:", err2);
    return null;
  }
}
async function runTriagePipeline(session, issueNumber, issueDetails) {
  const { data: reproduceResult } = await session.skill("triage", {
    args: {
      issueNumber,
      issueDetails,
      step: "reproduce",
      instructions: 'Run only the "reproduce" sub-skill from reproduce.md. Do not continue to diagnose, verify, or fix steps.'
    },
    result: object({
      reproducible: pipe(
        boolean(),
        description("true if the bug was successfully reproduced, false otherwise")
      ),
      skipped: pipe(
        boolean(),
        description(
          "true if reproduction was intentionally skipped (host-specific, unsupported version, etc.)"
        )
      ),
      skippedReason: pipe(
        nullable(
          picklist([
            "not-actionable",
            "missing-details",
            "unsupported-version",
            "host-specific",
            "unsupported-runtime",
            "maintainer-override"
          ])
        ),
        description("The reason reproduction was skipped, or null if not skipped")
      )
    })
  });
  if (reproduceResult.skipped || !reproduceResult.reproducible) {
    return {
      completedStage: "reproduce",
      reproducible: reproduceResult.reproducible,
      skipped: reproduceResult.skipped,
      skippedReason: reproduceResult.skippedReason,
      verdict: null,
      diagnosisConfidence: null,
      fixed: false,
      commitMessage: null
    };
  }
  const { data: diagnoseResult } = await session.skill("triage", {
    args: {
      issueDetails,
      step: "diagnose",
      instructions: 'Run only the "diagnose" sub-skill from diagnose.md. Do not continue to verify or fix steps.'
    },
    result: object({
      confidence: pipe(
        nullable(picklist(["high", "medium", "low"])),
        description("Diagnosis confidence level, null if not attempted")
      )
    })
  });
  const { data: verifyResult } = await session.skill("triage", {
    args: {
      issueDetails,
      step: "verify",
      instructions: 'Run only the "verify" sub-skill from verify.md. Do not continue to fix step.'
    },
    result: object({
      verdict: pipe(
        picklist(["bug", "intended-behavior", "unclear"]),
        description("Whether the reported behavior is a bug, intended behavior, or unclear")
      ),
      confidence: pipe(
        picklist(["high", "medium", "low"]),
        description("Confidence level in the verdict")
      )
    })
  });
  if (verifyResult.verdict === "intended-behavior") {
    return {
      completedStage: "verify",
      reproducible: true,
      skipped: false,
      skippedReason: null,
      verdict: verifyResult.verdict,
      diagnosisConfidence: diagnoseResult.confidence,
      fixed: false,
      commitMessage: null
    };
  }
  const { data: fixResult } = await session.skill("triage", {
    args: {
      issueDetails,
      step: "fix",
      instructions: 'Run only the "fix" sub-skill from fix.md.'
    },
    result: object({
      fixed: pipe(
        boolean(),
        description("true if the bug was successfully fixed and verified")
      ),
      commitMessage: pipe(
        nullable(string()),
        description("A short commit message describing the fix. null if not fixed.")
      )
    })
  });
  return {
    completedStage: "fix",
    reproducible: true,
    skipped: false,
    skippedReason: null,
    verdict: verifyResult.verdict,
    diagnosisConfidence: diagnoseResult.confidence,
    fixed: fixResult.fixed,
    commitMessage: fixResult.commitMessage
  };
}
async function selectTriageLabels(session, {
  comment,
  priorityLabels,
  packageLabels
}) {
  const priorityLabelNames = priorityLabels.map((l10) => l10.name);
  const packageLabelNames = packageLabels.map((l10) => l10.name);
  const { data: labelResult } = await session.prompt(
    `Label the following GitHub issue based on the triage report that was already posted.

Select labels for this issue from the lists below based on the triage report. Select exactly one priority label (the report's **Priority** section is a strong hint) and 0-3 package labels based on where the issue lives in the monorepo and how it manifests.

### Priority Labels (select exactly one)
${priorityLabels.map((l10) => `- "${l10.name}": ${l10.description || "(no description)"}`).join("\n")}

### Package Labels (select zero or more)
${packageLabels.map((l10) => `- "${l10.name}": ${l10.description || "(no description)"}`).join("\n")}

--- 

<triage-report format="md">
${comment}
</triage-report>
`,
    {
      result: object({
        priority: pipe(
          picklist(priorityLabelNames),
          description(
            "The priority label to apply. Must be one of the exact priority label names listed above."
          )
        ),
        packages: pipe(
          array(picklist(packageLabelNames)),
          description(
            "Package labels to apply (0-3). Each must be one of the exact package label names listed above."
          )
        )
      })
    }
  );
  return [labelResult.priority, ...labelResult.packages];
}
function resolveTriageLabel(result, ctx, previewRelease, prOpened) {
  if (result.skipped) {
    if (result.skippedReason === "not-actionable") return ctx.labels.notActionable;
    if (result.skippedReason === "missing-details") return ctx.labels.needsReproduction;
    return ctx.labels.skipped;
  }
  if (!result.reproducible) return ctx.labels.unableToReproduce;
  if (result.fixed) {
    if (prOpened) return ctx.labels.fixVerified;
    return previewRelease ? ctx.labels.fixPending : ctx.labels.needsTriage;
  }
  return ctx.labels.unableToFix;
}
function countTriageFailures(issueDetails) {
  return issueDetails.comments.filter((comment) => comment.body.includes(TRIAGE_FAILURE_MARKER)).length;
}
function currentRunUrl(ctx) {
  const runId = process.env.GITHUB_RUN_ID;
  if (!runId) return null;
  const serverUrl = process.env.GITHUB_SERVER_URL || "https://github.com";
  return `${serverUrl}/${ctx.repo}/actions/runs/${runId}`;
}
function formatFailureComment(error51, attempt, ctx) {
  const runUrl = currentRunUrl(ctx);
  const message = error51 instanceof Error ? error51.message : String(error51);
  const retryMessage = attempt >= MAX_TRIAGE_FAILURES ? "This was the final automatic triage attempt. I will not retry this issue again unless a maintainer clears the failure state manually." : "I can retry if a new comment provides more information or asks me to try again.";
  return `${TRIAGE_FAILURE_MARKER}
Triage failed unexpectedly (attempt ${attempt} of ${MAX_TRIAGE_FAILURES}).

${runUrl ? `Run: ${runUrl}

` : ""}${retryMessage}

Error:

\`\`\`
${message}
\`\`\``;
}
async function recordTriageFailure(issueNumber, ctx, error51) {
  const issueDetails = await fetchIssueDetails(ctx.repo, issueNumber, ctx.readToken);
  const attempt = Math.min(countTriageFailures(issueDetails) + 1, MAX_TRIAGE_FAILURES);
  const currentLabel = currentTriageLabel(
    issueDetails.labels.map((l10) => l10.name),
    ctx.labels
  );
  await postComment(
    ctx.repo,
    issueNumber,
    formatFailureComment(error51, attempt, ctx),
    ctx.writeToken
  );
  await swapLabel(ctx.repo, issueNumber, currentLabel, ctx.labels.failed, ctx.writeToken);
}
async function handleTriage(issueNumber, ctx) {
  try {
    await runTriage(issueNumber, ctx);
  } catch (err2) {
    try {
      await recordTriageFailure(issueNumber, ctx, err2);
    } catch (failureErr) {
      console.error("Failed to record triage failure:", failureErr);
    }
    throw err2;
  }
}
async function runTriage(issueNumber, ctx) {
  const branch = `triagebot/fix-${issueNumber}`;
  const issueDetails = await fetchIssueDetails(ctx.repo, issueNumber, ctx.readToken);
  const currentLabel = currentTriageLabel(
    issueDetails.labels.map((l10) => l10.name),
    ctx.labels
  );
  if (currentLabel === ctx.labels.failed && countTriageFailures(issueDetails) >= MAX_TRIAGE_FAILURES) {
    console.info(`Skipping triage for issue #${issueNumber}: maximum failed attempts reached.`);
    return;
  }
  const agent = createAgent(() => ({
    sandbox: local({
      env: {
        GH_TOKEN: ctx.readToken,
        GITHUB_ACTIONS: process.env.GITHUB_ACTIONS,
        GITHUB_REPOSITORY: process.env.GITHUB_REPOSITORY,
        GITHUB_RUN_ID: process.env.GITHUB_RUN_ID,
        GITHUB_RUN_ATTEMPT: process.env.GITHUB_RUN_ATTEMPT,
        GITHUB_ACTOR_ID: process.env.GITHUB_ACTOR_ID,
        GITHUB_SHA: process.env.GITHUB_SHA,
        GITHUB_REF_NAME: process.env.GITHUB_REF_NAME,
        GITHUB_OUTPUT: process.env.GITHUB_OUTPUT,
        GITHUB_EVENT_PATH: process.env.GITHUB_EVENT_PATH
      }
    }),
    model: ctx.triageModel
  }));
  const session = await createSession(agent);
  await session.shell(`git checkout -B ${JSON.stringify(branch)}`);
  const triageResult = await runTriagePipeline(session, issueNumber, issueDetails);
  console.info("Triage pipeline result:", triageResult);
  let isPushed = false;
  {
    const diff = await session.shell("git diff main --stat");
    console.info(`Triage diff stat present: ${Boolean(diff.stdout.trim())}`);
    if (diff.stdout.trim()) {
      const status = await session.shell("git status --porcelain");
      console.info(`Triage worktree status present: ${Boolean(status.stdout.trim())}`);
      if (status.stdout.trim()) {
        const defaultMessage = triageResult.fixed ? "fix(auto-triage): automated fix" : "test(auto-triage): failing test and investigation notes";
        const commitMessage = triageResult.commitMessage ?? defaultMessage;
        console.info(`Triage committing changes with message: ${commitMessage}`);
        const commitResult = await gitCommit(commitMessage);
        if (commitResult.exitCode !== 0) {
          throw new Error(
            `git commit failed (exit ${commitResult.exitCode}): ${commitResult.stderr || commitResult.stdout}`
          );
        }
      }
      const pushResult = await gitPush(ctx.repo, branch, ctx.writeToken, { force: true });
      console.info("push result:", pushResult);
      isPushed = pushResult.exitCode === 0;
    }
  }
  console.info(`Triage branch pushed: ${isPushed}`);
  let previewRelease = null;
  let openedPr = null;
  if (triageResult.fixed && isPushed) {
    if (ctx.autoPrOnFix) {
      openedPr = await findPullRequest(ctx.repo, branch, ctx.readToken);
      if (openedPr) {
        console.info(`Auto-PR skipped: PR already exists at ${openedPr.html_url}.`);
      } else {
        const prContent = await generatePRContent(
          session,
          { issueNumber, issueDetails, branch },
          ctx
        );
        openedPr = await createPullRequest(
          ctx.repo,
          { head: branch, base: "main", title: prContent.title, body: prContent.body },
          ctx.writeToken
        );
        console.info(`Auto-PR created: ${openedPr.html_url}`);
        await addLabels(ctx.repo, openedPr.number, [ctx.labels.prFixVerified], ctx.writeToken);
      }
    } else {
      previewRelease = await publishPreviewRelease(session);
      if (previewRelease) {
        console.info("Preview release published:", previewRelease.urls);
      } else {
        console.info("Preview release unavailable for fixed issue.");
      }
    }
  } else {
    console.info(
      `Preview release / auto-PR skipped: fixed=${triageResult.fixed} branchPushed=${isPushed}.`
    );
  }
  const { priorityLabels, packageLabels } = await fetchRepoLabels(ctx.repo, ctx.readToken);
  const branchName = isPushed ? branch : null;
  let comment = await generateComment(session, {
    branchName,
    priorityLabels,
    issueDetails,
    repo: ctx.repo,
    previewRelease
  });
  console.info(`Generated triage comment (${comment.length} chars).`);
  if (openedPr) {
    comment += `

I've opened a pull request with this fix: ${openedPr.html_url}`;
  }
  await postComment(ctx.repo, issueNumber, comment, ctx.writeToken);
  console.info(`Posted triage comment for issue #${issueNumber}.`);
  const newLabel = resolveTriageLabel(triageResult, ctx, previewRelease, Boolean(openedPr));
  console.info(`Swapping triage label from ${currentLabel ?? "(none)"} to ${newLabel}.`);
  await swapLabel(ctx.repo, issueNumber, currentLabel, newLabel, ctx.writeToken);
  if (triageResult.reproducible) {
    const selectedLabels = await selectTriageLabels(session, {
      comment,
      priorityLabels,
      packageLabels
    });
    console.info("Selected additional labels:", selectedLabels);
    if (selectedLabels.length > 0) {
      await addLabels(ctx.repo, issueNumber, selectedLabels, ctx.writeToken);
    }
  }
}

// src/handlers/retriage.ts
async function handleRetriage(issueNumber, currentLabel, ctx) {
  const issueDetails = await fetchIssueDetails(ctx.repo, issueNumber, ctx.readToken);
  if (currentLabel === ctx.labels.failed && countTriageFailures(issueDetails) >= MAX_TRIAGE_FAILURES) {
    console.info(`Retriage skipped for issue #${issueNumber}: maximum failed attempts reached.`);
    return;
  }
  const agent = createAgent(() => ({
    sandbox: local({
      env: { GH_TOKEN: ctx.readToken }
    }),
    model: ctx.verificationModel
  }));
  const session = await createSession(agent);
  const { data: decision } = await session.prompt(
    `You are reviewing a GitHub issue conversation to decide whether a triage re-run is warranted.

## Issue
**${issueDetails.title}**

${issueDetails.body}

## Conversation
${issueDetails.comments.map((c14) => `**@${c14.author.login}:**
${c14.body}`).join("\n\n---\n\n")}

## Your Task
Look at the messages since the last comment from a bot account.
Consider comments from the original poster, maintainers, or other users who may have provided:
- New reproduction steps or environment details
- Corrections to a previously attempted reproduction
- Additional context about when/how the bug occurs
- Different configurations or versions to try

Then decide how to respond:
1. If there is new, actionable information that could lead to a different reproduction result
than what was already attempted, respond with "yes".
2. If someone is intentionally asking you to retry triage, respond with "yes".
3. If the new comments are just acknowledgments, thanks, unrelated discussion, or do not add
meaningful reproduction information, respond with "no".

Return only "yes" or "no" inside the ---RESULT_START--- / ---RESULT_END--- block.`,
    { result: picklist(["yes", "no"]) }
  );
  if (decision === "no") {
    console.info(`Retriage not warranted for issue #${issueNumber}`);
    return;
  }
  console.info(`Retriaging issue #${issueNumber}`);
  await swapLabel(ctx.repo, issueNumber, currentLabel, ctx.labels.needsTriage, ctx.writeToken);
  await handleTriage(issueNumber, ctx);
}

// src/handlers/verify-fix.ts
async function handleVerifyFix(issueNumber, ctx) {
  const branch = await findBranch(
    ctx.repo,
    [`triagebot/fix-${issueNumber}`, `flue/fix-${issueNumber}`],
    ctx.readToken
  );
  if (!branch) {
    throw new Error(`No fix branch found for issue #${issueNumber}`);
  }
  const issueDetails = await fetchIssueDetails(ctx.repo, issueNumber, ctx.readToken);
  const latestUserComment = [...issueDetails.comments].reverse().find((c14) => !ctx.botLogins.includes(c14.author.login));
  if (!latestUserComment) {
    console.info("No user comment found, skipping verification.");
    return;
  }
  const agent = createAgent(() => ({
    sandbox: local({
      env: { GH_TOKEN: ctx.readToken }
    }),
    model: ctx.verificationModel
  }));
  const session = await createSession(agent);
  const { data: classification } = await session.prompt(
    `You are reviewing a GitHub issue comment to determine if the commenter is confirming that a proposed fix works.

## Context

An automated triage bot found a fix for issue #${issueNumber} and published a preview release for the reporter to test. The bot asked the reporter to install the preview and confirm whether the fix resolves their issue.

## Issue
**${issueDetails.title}**

${issueDetails.body}

## Recent conversation
${issueDetails.comments.slice(-10).map((c14) => `**@${c14.author.login}** (${c14.authorAssociation}):
${c14.body}`).join("\n\n---\n\n")}

## Comment to classify
**@${latestUserComment.author.login}** (${latestUserComment.authorAssociation}):
${latestUserComment.body}

## Your Task

Determine if this comment is a **positive confirmation** that the fix works. Examples of positive confirmation:
- "It works!"
- "Confirmed, this fixes my issue"
- "Tested the preview release, the bug is gone"
- "Thanks, that solved it"
- Thumbs up or similar positive reaction with clear reference to testing

Determine if this comment is a **negative confirmation** that the fix does NOT work. Examples:
- "Still broken"
- "Same error"
- "The fix doesn't work"
- "Tried the preview, issue persists"

Examples of comments that are NEITHER (inconclusive):
- Asking questions ("How do I install this?")
- Unrelated discussion
- Acknowledgment without testing ("Thanks, I'll try it later")

Return your classification.`,
    {
      result: object({
        status: pipe(
          picklist(["confirmed", "rejected", "inconclusive"]),
          description(
            "confirmed = fix works, rejected = fix does not work, inconclusive = neither"
          )
        ),
        reasoning: pipe(
          string(),
          description("Brief explanation of why you classified this way")
        )
      })
    }
  );
  console.info("Verification classification:", classification);
  if (classification.status === "inconclusive") {
    console.info("Comment is inconclusive, taking no action.");
    return;
  }
  if (classification.status === "rejected") {
    await swapLabel(
      ctx.repo,
      issueNumber,
      ctx.labels.fixPending,
      ctx.labels.fixRejected,
      ctx.writeToken
    );
    return;
  }
  const existingPr = await findPullRequest(ctx.repo, branch, ctx.readToken);
  if (existingPr) {
    console.info(`PR already exists: ${existingPr.html_url}`);
    await swapLabel(
      ctx.repo,
      issueNumber,
      ctx.labels.fixPending,
      ctx.labels.fixVerified,
      ctx.writeToken
    );
    await postComment(
      ctx.repo,
      issueNumber,
      `The fix has been verified! A pull request already exists: ${existingPr.html_url}`,
      ctx.writeToken
    );
    return;
  }
  const prOpts = {
    issueNumber,
    issueDetails,
    branch,
    confirmedBy: latestUserComment.author.login
  };
  const prContent = await generatePRContent(session, prOpts, ctx);
  const pr4 = await createPullRequest(
    ctx.repo,
    { head: branch, base: "main", title: prContent.title, body: prContent.body },
    ctx.writeToken
  );
  console.info(`PR created: ${pr4.html_url}`);
  await addLabels(ctx.repo, pr4.number, [ctx.labels.prFixVerified], ctx.writeToken);
  await swapLabel(
    ctx.repo,
    issueNumber,
    ctx.labels.fixPending,
    ctx.labels.fixVerified,
    ctx.writeToken
  );
  await postComment(
    ctx.repo,
    issueNumber,
    `The fix has been verified! A pull request has been created: ${pr4.html_url}`,
    ctx.writeToken
  );
}

